__def("src/screen/texts.js", function () {
const STATUS_LABEL = { draft: 'Draft', ready: 'Ready', inKindroid: 'In Kindroid', outdated: 'Outdated' };
const STATUS_HINT = {
  draft: 'Still being written.',
  ready: 'Passes the rules. Ready to paste into Kindroid.',
  inKindroid: 'You marked it as added to the Kin\'s Journal in Kindroid.',
  outdated: 'Changed after it went to Kindroid. Update it there, then mark it again.',
};
const SAVE_LABEL = { saved: 'Saved', unsaved: 'Edited', saving: 'Saving…', failed: 'Not saved' };
const FILTERS = [['all', 'All'], ['draft', 'Drafts'], ['ready', 'Ready'], ['inKindroid', 'In Kindroid'], ['outdated', 'Outdated'], ['issues', 'Warnings']];

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

function excerpt(text, max = 130) {
  const flat = text.replace(/\s+/g, ' ').trim();
  return flat.length > max ? `${flat.slice(0, max).trimEnd()}…` : flat;
}

function shortDate(iso, now = new Date()) {
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) return '';
  if (d.toDateString() === now.toDateString()) return d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: d.getFullYear() === now.getFullYear() ? undefined : 'numeric' });
}

function collectionTitle(collection, kins, names) {
  if (collection.kind === 'all') return 'All entries';
  if (collection.kind === 'global') return 'Global';
  if (collection.kind === 'unassigned') return 'No Kin';
  const kin = kins.find((k) => k.id === collection.kinId);
  return kin ? kin.name : names[collection.kinId] || 'Detached Kin';
}
return { STATUS_LABEL, STATUS_HINT, SAVE_LABEL, FILTERS, plural, excerpt, shortDate, collectionTitle };
});

